	private JCLiteral buildNullCheckMessageLiteral(JavacTreeMaker maker) {
		NullCheckExceptionType exceptionType = this.nullCheckExceptionType;
		if (exceptionType == null) exceptionType = NullCheckExceptionType.NULL_POINTER_EXCEPTION;
		String varName = this.nullCheckVarName == null ? "arg" : this.nullCheckVarName.toString();
