	private JCStatement buildAssertionNullCheck(JavacTreeMaker maker) {
		JCLiteral message = buildNullCheckMessageLiteral(maker);
		return maker.Assert(maker.Binary(CTC_NOT_EQUAL, maker.Ident(this.nullCheckVarName), maker.Literal(CTC_BOT, null)), message);
	}

	private JCStatement buildMethodCallNullCheck(JavacTreeMaker maker, lombok.core.LombokImmutableList<String> method) {
		if (this.nullCheckSource == null || method == null) return null;
		JCLiteral message = buildNullCheckMessageLiteral(maker);
		return maker.Exec(maker.Apply(List.<JCExpression>nil(), chainDots(this.nullCheckSource, method), List.of(maker.Ident(this.nullCheckVarName), message)));
	}

	private JCStatement buildIfThrowNullCheck(JavacTreeMaker maker) {
		if (this.nullCheckSource == null) return null;
		NullCheckExceptionType exceptionType = this.nullCheckExceptionType;
		if (exceptionType == null) exceptionType = NullCheckExceptionType.NULL_POINTER_EXCEPTION;
		JCLiteral message = buildNullCheckMessageLiteral(maker);
		JCExpression exType = genTypeRef(this.nullCheckSource, exceptionType.getExceptionType());
		JCExpression exception = maker.NewClass(null, List.<JCExpression>nil(), exType, List.<JCExpression>of(message), null);
		JCStatement throwStatement = maker.Throw(exception);
		JCBlock throwBlock = maker.Block(0, List.of(throwStatement));
		return maker.If(maker.Binary(CTC_EQUAL, maker.Ident(this.nullCheckVarName), maker.Literal(CTC_BOT, null)), throwBlock, null);
	}

