import com.sun.source.util.*;
import javax.tools.*;
import java.net.*;
import java.util.*;

public class Dump {
  public static void main(String[] args) throws Exception {
    JavaCompiler c = ToolProvider.getSystemJavaCompiler();
    JavaFileObject f = new SimpleJavaFileObject(URI.create("string:///Sample.java"), JavaFileObject.Kind.SOURCE) {
      public CharSequence getCharContent(boolean b) { return "public record Sample(int @A [] a, int[] @A [] b, int @A [] [] c, int[] @A [] [] d) {}\n@interface A {}\n"; }
    };
    JavacTask task = (JavacTask) c.getTask(null, null, null, Arrays.asList("-proc:none"), null, Arrays.asList(f));
    Iterable<? extends CompilationUnitTree> units = task.parse();
    new TreePathScanner<Void,Void>() {
      int depth=0;
      public Void scan(Tree t, Void p) {
        if (t != null) {
          String s = t.getKind().toString();
          if (t instanceof VariableTree) s += " name="+((VariableTree)t).getName();
          if (t instanceof AnnotatedTypeTree) s += " anns="+((AnnotatedTypeTree)t).getAnnotations();
          if (t instanceof ArrayTypeTree) s += " arr";
          System.out.println("  ".repeat(depth)+s+" ["+t.getClass().getName()+"]");
        }
        depth++; Void v=super.scan(t,p); depth--; return v;
      }
    }.scan(units, null);
  }
}
